package br.edu.mediconnect; import br.edu.mediconnect.model.*; import br.edu.mediconnect.patterns.facade.MediConnectFacade; import br.edu.mediconnect.patterns.factory.AppointmentFactory;
public class Main { public static void main(String[] args){ MediConnectFacade app=new MediConnectFacade(); app.registerPatient(new Patient("P1","Ana","PLAN-A","62999999999","ana@example.com")); Appointment a=AppointmentFactory.create("CONSULTATION","A1","P1","D1","2026-08-20T19:00"); System.out.println("Agendada: "+app.schedule(a)+" status="+a.status); ExamRequest e=new ExamRequest("E1","P1","HEMOGRAMA"); System.out.println("Exame autorizado: "+app.requestExam(e,150)+" status="+e.status); } }
